def admit(active, waiting, budget, slots):
    # Αν οποιαδήποτε αναμένουσα κράτηση ξεπερνά το συνολικό budget, σήκωσε ValueError
    for value in waiting:
        if value > budget:
            raise ValueError(f"Reservation {value} exceeds total budget {budget}")

    available_slots = slots - len(active)
    used = sum(active)
    admitted = []

    for value in waiting:
        if used + value <= budget and len(admitted) + 1 <= available_slots:
            admitted.append(value)
            used += value
        else:
            break  # Σταματά στην πρώτη που δεν χωρά, δεν προσπερνά

    remaining = waiting[len(admitted):]
    return admitted, remaining

