def admit(active, waiting, budget, slots):
    waiting = list(waiting)
    for value in waiting:
        if value > budget:
            raise ValueError(
                "waiting reservation %r exceeds total budget %r" % (value, budget)
            )
    admitted = []
    active_total = sum(active)
    admitted_total = 0
    for value in waiting:
        if (active_total + admitted_total + value <= budget
                and len(active) + len(admitted) + 1 <= slots):
            admitted.append(value)
            admitted_total += value
        else:
            break
    return admitted, waiting[len(admitted):]
